  return lines
}

function processNormalize(record) {
  const parsed = parseReference(record)
  normalize(parsed)
  return serializeReference(parsed)
}

function processResolve(record) {
  const space = record.indexOf(' ')
  if (space === -1) throw new RecordError('expected a base and a reference')
  const base = parseReference(record.slice(0, space))
  const ref = parseReference(record.slice(space + 1))
  if (base.scheme === null) throw new RecordError('the base has no scheme')
  return serializeReference(resolve(base, ref))
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')
  const records = splitRecords(input)
  const processRecord = mode === 'normalize' ? processNormalize : processResolve

  const results = []
  for (let i = 0; i < records.length; i++) {
    try {
      results.push(processRecord(records[i]))
    } catch (error) {
      process.stderr.write(`error: line ${i + 1}: ${error.message}\n`)
      process.exit(2)
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
